import { MONSTERS, monster } from '../rules/monsters'
const id = computed(() => (void gs.value, active())); const G = computed(() => gs.value); const h = computed(() => G.value?.chars[id.value]), m = computed(() => G.value?.mons[id.value]); const S = computed(() => h.value ? (void G.value, sheet(h.value)) : null); const cur = computed(() => { const c = G.value?.combat; return c ? c.order[c.i]?.id : null }); const mine = computed(() => !G.value?.combat || cur.value === id.value); const econ = computed(() => G.value?.combat?.econ[id.value] ?? null); const left = computed(() => { void G.value; return G.value?.combat ? peek()?.moveLeft(id.value) ?? 0 : -1 }); const tab = ref('attack'); const lv = ref(0)
const TABS = computed(() => [['attack', 'Attacks', 'crossed-swords'], ...(h.value && !h.value.shape && S.value && castable(S.value).length ? [['spells', 'Spells', 'spell-book']] : []), ...(h.value ? [['feats', 'Class', 'muscle-up']] : []), ['acts', 'Actions', 'run'], ...(h.value ? [['items', 'Items', 'knapsack']] : [])]); watch(id, () => { if (!TABS.value.some(t => t[0] === tab.value)) tab.value = 'attack' })
interface Slot { id: string; n: string; i: string; tip: string; sub?: string; off?: boolean; on?: boolean; go: () => void; cls?: string }
const base = (k: Aim['k'], a: Partial<Aim> & { id: string; name: string; icon: string; range: number; want: Aim['want'] }): Aim => ({ k, who: id.value, n: 1, ids: [], ...a }); const aim = (a: Aim) => app.aim && app.aim.id === a.id && app.aim.k === a.k ? aimAt(null) : aimAt(a)
const attacks = computed<Slot[]>(() => { void G.value; const R = peek(); if (!R || !id.value) return []; const L: Slot[] = R.attacksOf(id.value).map(a => ({ id: a.id, n: a.name, i: a.icon, sub: `${a.hit >= 0 ? '+' : '−'}${Math.abs(a.hit)}, ${a.dmg}`, tip: `${a.name}: ${a.hit >= 0 ? '+' : ''}${a.hit} to hit, ${a.dmg} ${a.type}, ${a.ranged ? a.range.join('/') : a.reach} ft`, off: !!econ.value && econ.value.act < 1 && econ.value.atk < 1 && !econ.value.flags.haste, on: app.aim?.k === 'attack' && app.aim.id === a.id && !app.aim.off, go: () => aim(base('attack', { id: a.id, name: a.name, icon: a.icon, range: a.ranged ? Math.max(...a.range) : a.at?.thrown ? Math.max(a.reach, ...a.range) : a.reach, want: m.value ? 'any' : 'foe' })) })); const off = h.value?.inv.find(s => s.eq === 'off'); if (h.value && off && item(off.id).kind === 'weapon') L.splice(1, 0, { id: 'off', n: item(off.id).name, i: item(off.id).icon, sub: 'off hand', tip: 'Strike with the off hand (bonus action)', off: !!econ.value && (econ.value.bonus < 1 || !econ.value.swung), go: () => aim(base('attack', { id: off.uid, name: item(off.id).name, icon: item(off.id).icon, range: 5, want: 'foe', off: true })) }); const M = m.value ? monster(m.value.ref) : null; if (M) for (const a of M.acts) if (a.k === 'save' || a.k === 'spell') L.push({ id: a.n, n: a.n.replace(/_/g, ' '), i: a.k === 'spell' ? 'spell-book' : 'fire-breath', tip: a.n, off: !!m.value!.used['a:' + a.n] && !!a.rc, go: () => a.area && !a.range?.[0] ? fire(base('special', { id: a.n, name: a.n, icon: '', range: 0, want: 'point' }), [], null) : aim(base('special', { id: a.n, name: a.n, icon: 'fire-breath', range: a.range?.[0] || a.size || 60, want: a.area ? 'point' : 'any', area: a.area, r: a.size, self: a.area === 'cone' || a.area === 'line' })) }); return L })
const slots = computed(() => { const s = S.value; if (!s) return []; const o: { l: number; left: number; max: number }[] = []; for (let l = 1; l <= 9; l++) { const max = (s.slots[l - 1] ?? 0) + (s.pact[1] === l ? s.pact[0] : 0); if (max) o.push({ l, max, left: max - (h.value!.slots[l] ?? 0) - (s.pact[1] === l ? h.value!.pact : 0) }) } return o })
const cast = (s: Spell) => { const fx = s.fx, l = Math.max(s.lv, lv.value); const up = Math.max(0, l - s.lv); const n = fx.kind === 'attack' && fx.beams && !fx.cantrip ? fx.beams + (fx.beamUp ?? 0) * up : fx.kind === 'auto' && fx.beams ? 1 : (fx.targets ?? 1) + (fx.targetUp ?? 0) * up; const self = fx.self && !fx.area; const lo = { lv: l || undefined }; if (self || (fx.self && fx.allies) || (fx.kind === 'zone' && fx.self) || (fx.area === 'sphere' && fx.self) || (fx.kind === 'utility' && !['misty_step', 'dimension_door', 'dispel', 'lesser_restoration', 'greater_restoration', 'remove_curse', 'spare_dying'].includes(s.id))) { void act({ k: 'cast', s: s.id, t: [id.value], ...lo }, id.value); return } aim(base('cast', { id: s.id, name: s.name, icon: spellIcon(s), range: Math.max(5, s.range), want: fx.area || ['misty_step', 'dimension_door'].includes(s.id) ? 'point' : ['heal', 'buff', 'revive'].includes(fx.kind) && fx.fx !== 'hunters_mark' && fx.fx !== 'hex' ? 'friend' : fx.kind === 'utility' ? 'any' : fx.fx === 'hunters_mark' || fx.fx === 'hex' ? 'foe' : 'foe', n: Math.min(n, ['heal', 'buff'].includes(fx.kind) ? Math.max(1, Math.min(n, Object.keys(G.value!.chars).length)) : n), area: fx.area, r: fx.size, self: fx.self, lv: l || undefined })) }
const spells = computed<Slot[]>(() => { const s = S.value; if (!s || !h.value) return []; return castable(s).filter(x => !G.value!.combat || x.time !== 'long').sort((a, b) => a.lv - b.lv || a.name.localeCompare(b.name)).map(x => ({ id: x.id, n: x.name, i: spellIcon(x), sub: x.lv ? 'level ' + x.lv : 'cantrip', tip: `${x.name}\n${x.text}\n${x.time}, ${x.range ? x.range + ' ft' : 'self'}${x.conc ? ', concentration' : ''}`, off: (x.lv > 0 && !peek()?.spendSlot(h.value!, Math.max(x.lv, lv.value), true)) || (!!econ.value && (x.time === 'bonus' ? econ.value.bonus < 1 : x.time === 'action' ? econ.value.act < 1 && !G.value!.arm[id.value]?.quicken : x.time === 'reaction')), on: app.aim?.id === x.id, cls: 'lv' + Math.min(5, x.lv), go: () => cast(x) })) })
const NEED: Record<string, [Aim['want'], number] | undefined> = { frenzy: ['foe', 5], presence: ['foe', 30], inspire: ['friend', 60], martial: ['foe', 5], flurry: ['foe', 5], palm: ['foe', 5], lay: ['friend', 5], cleansing: ['friend', 5], volley: ['point', 150] }
const feats = computed<Slot[]>(() => { const s = S.value, H = h.value; if (!s || !H) return []; const out: Slot[] = []; const arm = G.value!.arm[id.value] ?? {}; for (const f of s.cls.features) { if (!f.act || f.lv > H.level || ['cunning', 'fasthands', 'countercharm', 'luck', 'indom', 'stroke', 'lore', 'deflect', 'uncanny', 'retaliation', 'hurl', 'hunters'].includes(f.id)) continue; const max = f.res ? s.resMax[f.res] : 0, leftN = f.res ? max - (H.res[f.res] ?? 0) : -1; if (f.id === 'shape') { if (H.shape) out.push({ id: 'unshape', n: 'Own form', i: 'character', tip: 'Return to your own form', go: () => void act({ k: 'feat', f: 'shape' }, id.value) }); else { const cap = H.level >= 8 ? 1 : H.level >= 4 ? .5 : .25; for (const M of MONSTERS.filter(x => x.type === 'beast' && x.cr <= cap && (!x.fly || H.level >= 8)).sort((a, b) => b.cr - a.cr || b.hp - a.hp).slice(0, 5)) out.push({ id: 'shape' + M.id, n: M.name, i: 'wolf-head', sub: leftN + ' left', tip: `Take the shape of a ${M.name.toLowerCase()}: ${M.hp} HP, AC ${M.ac}`, off: leftN <= 0, go: () => void act({ k: 'feat', f: 'shape', form: M.id }, id.value) }) } continue } const key = f.id === 'stunning' ? 'stun' : f.id; out.push({ id: f.id, n: f.name, i: ({ rage: 'enrage', wind: 'heart-plus', surge: 'sprint', inspire: 'musical-notes', turn: 'sunbeams', preserve: 'heart-wings', flurry: 'fist', patient: 'dodging', stepwind: 'wingfoot', stunning: 'knocked-out-stars', lay: 'healing', smite: 'sunbeams', sacred: 'sparkling-sabre', sense: 'all-seeing-eye', reckless: 'axe-swing', frenzy: 'battered-axe', quicken: 'lightning-trio', empower: 'fire-ring', flexible: 'crystal-growth', vanish: 'hooded-figure', volley: 'arrow-cluster', martial: 'punch' } as any)[f.id] ?? 'star-formation', sub: f.res && max < 50 ? `${leftN} left` : ['smite', 'stunning', 'quicken', 'empower', 'overchannel'].includes(f.id) ? (arm[key] ? 'ready' : 'arm') : f.act, tip: `${f.name}\n${f.text}`, off: (f.res && leftN <= 0) || (!!econ.value && ((f.act === 'bonus' && econ.value.bonus < 1) || (f.act === 'action' && econ.value.act < 1))) || undefined, on: !!arm[key] || H.conds.some(c => c.id === f.id) || app.aim?.id === f.id, go: () => { const q = NEED[f.id]; if (q) aim(base('feat', { id: f.id, name: f.name, icon: 'star-formation', range: q[1], want: q[0], area: f.id === 'volley' ? 'sphere' : undefined, r: 10 })); else void act({ k: 'feat', f: f.id, n: f.id === 'smite' ? Math.max(1, lv.value) : f.id === 'flexible' ? (slots.value.find(x => x.left < x.max)?.l ?? 1) : undefined }, id.value) } }) } if (H.race === 'dragonborn') out.push({ id: 'breath', n: 'Breath', i: 'fire-breath', sub: H.res.breath ? 'spent' : '1 left', tip: 'A 15-foot cone of fire', off: !!H.res.breath, go: () => aim(base('feat', { id: 'breath', name: 'Breath', icon: 'fire-breath', range: 15, want: 'point', area: 'cone', r: 15, self: true })) }); void has; return out })
const acts = computed<Slot[]>(() => { const A: [string, string, string, string, Aim['want']?][] = G.value?.combat ? [['dash', 'Dash', 'run', 'Move again this turn'], ['disengage', 'Disengage', 'backup', 'Leave without being struck'], ['dodge', 'Dodge', 'dodging', 'Attacks against you have disadvantage'], ['hide', 'Hide', 'hooded-figure', 'Slip out of sight'], ['help', 'Help', 'shaking-hands', 'Give a friend advantage, or steady the dying', 'friend'], ['shove', 'Shove', 'push', 'Knock a foe down', 'foe'], ['grapple', 'Grapple', 'grab', 'Seize a foe', 'foe'], ['search', 'Search', 'magnifying-glass', 'Find the hidden']] : [['sneak', 'Sneak', 'hooded-figure', 'Go softly; creatures may not notice'], ['help', 'Help', 'shaking-hands', 'Give a friend advantage', 'friend'], ['search', 'Search', 'magnifying-glass', 'Look for the hidden']]; const u = h.value ?? m.value; const out: Slot[] = A.map(a => ({ id: a[0], n: a[1], i: a[2], tip: `${a[1]}\n${a[3]}`, off: !!econ.value && econ.value.act < 1 && !(h.value && has(h.value, 'cunning') && ['dash', 'disengage', 'hide'].includes(a[0]) && econ.value.bonus > 0), on: a[0] === 'sneak' && G.value?.sneak[id.value] !== undefined, go: () => a[4] ? aim(base('act', { id: a[0], name: a[1], icon: a[2], range: 5, want: a[4] })) : void act({ k: 'act', a: a[0] }, id.value) })); if (u?.conds.some(c => c.id === 'prone') && !u.conds.some(c => c.id === 'unconscious')) out.unshift({ id: 'stand', n: 'Stand', i: 'character', tip: 'Stand up (half your movement)', go: () => void act({ k: 'act', a: 'stand' }, id.value) }); if (u?.conds.some(c => ['grappled', 'restrained'].includes(c.id))) out.unshift({ id: 'escape', n: 'Break free', i: 'breaking-chain', tip: 'Struggle loose', go: () => void act({ k: 'act', a: 'escape' }, id.value) }); if (h.value && !G.value?.combat) out.push({ id: 'short', n: 'Short rest', i: 'campfire', tip: 'An hour’s rest', go: () => void act({ k: 'rest', kind: 'short' }, id.value) }, { id: 'long', n: 'Long rest', i: 'night-sleep', tip: 'Sleep until morning', go: () => void act({ k: 'rest', kind: 'long' }, id.value) }); return out })
const items = computed<Slot[]>(() => (h.value?.inv ?? []).filter(s => { const i = item(s.id); return i.heal || i.use || i.spell || s.id === 'goodberry' }).map(s => { const i = item(s.id); return { id: s.uid, n: i.name, i: i.icon, sub: s.n > 1 ? '× ' + s.n : '', tip: `${i.name}\n${i.text ?? ''}`, off: !!econ.value && econ.value.act < 1, on: app.aim?.id === s.uid, go: () => { const th = i.use === 'throw' || (!!i.spell && !['cure_wounds', 'revivify', 'haste'].includes(i.spell)); if (th || i.heal || i.spell || i.use === 'stabilise') aim(base('item', { id: s.uid, name: i.name, icon: i.icon, range: th ? i.range?.[1] ?? 120 : 5, want: th ? 'foe' : 'friend' })); else void act({ k: 'item', u: s.uid }, id.value) } } }))
const list = computed(() => ({ attack: attacks.value, spells: spells.value, feats: feats.value, acts: acts.value, items: items.value } as Record<string, Slot[]>)[tab.value] ?? []); const fxs = computed(() => (h.value ?? m.value)?.conds.filter(c => c.kind === 'fx').map(c => EFFECTS[c.id]).filter(Boolean) ?? []); void fxs
</script>
<template><div v-if="h || m" class="hb paper" :class="{ idle: !mine, turn: mine && gs?.combat }"><div class="hd"><nav><button v-for="t in TABS" :key="t[0]" :class="{ on: tab === t[0] }" @click="tab = t[0]">{{ t[1] }}</button></nav><div v-if="tab === 'spells' && slots.length" class="sl"><button v-for="s in slots" :key="s.l" :class="{ on: lv === s.l, off: !s.left }" v-tip="lv === s.l ? 'Cast at each spell’s own level' : `Cast at level ${s.l}`" @click="lv = lv === s.l ? 0 : s.l">{{ s.l }}<u v-for="n in s.max" :key="n" :class="{ off: n > s.left }" /></button></div><span class="grow" /><div v-if="econ" class="ec"><span :class="{ off: econ.act < 1 && econ.atk < 1 }"><i />{{ econ.atk > 0 && econ.act < 1 ? `Attack${econ.atk > 1 ? ' × ' + econ.atk : ''}` : 'Action' }}</span><span :class="{ off: econ.bonus < 1 }"><i />Bonus</span><span :class="{ off: econ.react < 1 }"><i />Reaction</span><b>{{ app.budget >= 0 && id === app.seat && mine ? Math.min(app.budget, left) : left }} ft</b></div><button v-if="gs?.combat && (mine || app.role === 'dm')" class="end" @click="endTurn()">End turn<kbd>Space</kbd></button></div>
  <div class="slots scroll"><button v-for="s in list" :key="s.id" class="slot" :class="{ on: s.on, off: s.off || (!mine && !!gs?.combat) }" v-tip="s.tip" @click="s.go()"><span class="cut">{{ s.n }}</span><small v-if="s.sub" class="cut">{{ s.sub }}</small></button><span v-if="!list.length" class="none">{{ tab === 'items' ? 'Nothing in the pack to use.' : 'Nothing here.' }}</span></div></div></template>
<style scoped>
.hb{width:100%;min-width:0;pointer-events:auto;border-top:6px solid var(--ink)}.hb.turn{border-top-color:var(--spot)}.hd{display:flex;align-items:stretch;border-bottom:2px solid var(--ink);min-height:38px}nav{display:flex}nav button{padding:0 14px;font-weight:500;font-size:17px;color:var(--ink2)}nav button:hover{color:var(--ink);background:var(--paper2)}nav .on{background:var(--ink)!important;color:var(--paper)!important}
.sl{display:flex;align-items:center;gap:2px;padding-left:10px}.sl button{display:flex;align-items:center;gap:3px;padding:3px 7px;font:700 18px/1 var(--serif);height:30px}.sl .on{background:var(--spot);color:var(--on-spot)}.sl .off{opacity:.4}.sl u{width:9px;height:13px;border:2px solid currentColor;background:currentColor}.sl u.off{background:none}
.ec{display:flex;align-items:center;gap:13px;padding:0 14px;white-space:nowrap;font-size:15.5px}.ec span{display:flex;align-items:center;gap:6px}.ec i{width:15px;height:15px;border:2px solid var(--ink);background:var(--spot)}.ec .off{color:var(--ink3)}.ec .off i{border-color:var(--ink3);background:linear-gradient(45deg,transparent 42%,var(--ink3) 42% 58%,transparent 58%),linear-gradient(-45deg,transparent 42%,var(--ink3) 42% 58%,transparent 58%)}.ec b{font:700 20px/1 var(--serif);white-space:nowrap}nav button,.end{white-space:nowrap}.end{background:var(--spot);color:var(--on-spot);padding:0 18px;font:700 20px/1 var(--serif);display:flex;align-items:center;gap:10px}.end:hover{background:var(--ink);color:var(--paper)}.end kbd{font-family:var(--ui)}
.slots{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));max-height:112px;background:var(--paper)}.slot{min-height:56px;padding:7px 13px 6px;border-right:1px solid var(--line2);border-bottom:1px solid var(--line2);min-width:0;display:flex;flex-direction:column;justify-content:center}.slot span{font:700 19px/1.05 var(--serif)}.slot small{font-size:15px;line-height:1.15;color:var(--ink2)}.slot:hover{background:var(--paper2)}.slot.on{background:var(--spot);color:var(--on-spot)}.slot.on small{color:inherit}.slot.off span,.slot.off small{opacity:.42}.none{padding:17px 15px;color:var(--ink2)}
@media(max-width:899px){.hd{flex-wrap:wrap}nav{order:1;width:100%;overflow-x:auto;scrollbar-width:none;border-top:1px solid var(--line2)}nav button{flex:1;padding:0 8px;min-height:36px;text-align:center;font-size:16px}.ec{gap:11px;padding:0 10px;font-size:14.5px;height:34px}.end{padding:0 16px;font-size:18px;height:36px}.end kbd{display:none}.sl{order:2;width:100%;border-top:1px solid var(--line2);height:34px}.slots{grid-template-columns:none;grid-auto-flow:column;grid-auto-columns:minmax(112px,max-content);overflow-x:auto;max-height:none;scrollbar-width:none}.slot{min-height:50px;padding:5px 11px}.slot span{font-size:17.5px}.hb{border-top-width:4px}}
</style>
